import { CommonModule } from '@angular/common';
import { Component, signal } from '@angular/core';
import { RouterLink, RouterModule, RouterOutlet, UrlSerializer } from '@angular/router';
import { cleanUrlSerializer } from '../utils/clean-url-serializer';
import { Router } from 'express';
import { HomeContent } from '../home-content/home-content';
import { UserModel } from '../user/interfaces/user-model';
import { AuthenticationService } from '../user/userservices/authentication.service';

@Component({
  selector: 'home',
  imports: [CommonModule, RouterLink, HomeContent],
  templateUrl: './home.html',
  styleUrl: './home.css',
  providers: [
    {
      provide: UrlSerializer,
      useClass: cleanUrlSerializer
    }
  ]
})
export class Home {
  currentUser = signal<UserModel|null>(null);
  notlogin = signal<boolean>(true);

  constructor(
     //private router: Router
    private authenticationService: AuthenticationService
  ) {
    this.currentUser.set(this.authenticationService.currentUserValue);
    if (this.currentUser()) {
        this.notlogin.set(false);
    }
   
  }

  ngOnInit() {
     /*this.router.events.subscribe((event) => {
       console.log('Router event:', event);
       // You can check for specific events like NavigationStart, NavigationEnd, etc.
     });*/
  }

  signIn() {
  }

  signOut() {
    this.authenticationService.signOut();
    this.notlogin.update(() => true);
  }
}
